import React, { useState } from 'react';
import './Profil.css';
import TabNavigation from '../../components/shared/TabNavigation';

const Profil = () => {
  const [activeTab, setActiveTab] = useState('Informations');
  const [userData, setUserData] = useState({
    firstName: 'Pierre',
    lastName: 'Michel',
    email: 'pierremichel@gmail.com',
    birthDate: '25 Janvier 1990',
    password: '**********',
    address: '6 rue Firmin Oulès',
    postalCode: '81100',
    city: 'Castres',
    country: 'France'
  });

  const tabs = [
    'Informations',
    'Sécurité',
    'Préférences',
    'Notifications'
  ];

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setUserData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSave = () => {
    console.log('Données sauvegardées:', userData);
    // Ici vous ajouterez la logique pour sauvegarder les données
    alert('Modifications enregistrées avec succès!');
  };

  return (
    <div className="page-container">
      <div className="page-header">
        <h1>Modifier le profil</h1>
        <TabNavigation 
          tabs={tabs}
          activeTab={activeTab} 
          setActiveTab={setActiveTab} 
        />
      </div>
      
      <div className="profil-content">
        <div className="profil-card">
          <div className="profil-header">
            <div className="profil-avatar">
              <div className="avatar-circle">PM</div>
              <button className="change-avatar">Changer la photo</button>
            </div>
            
            <div className="profil-info">
              <h2>{userData.firstName} {userData.lastName}</h2>
              <p className="role">Transporteur coordinateur</p>
              <p className="email">{userData.email}</p>
            </div>
          </div>

          <div className="profil-form-section">
            <h3>Informations personnelles</h3>
            
            <div className="form-grid">
              <div className="form-group">
                <label>Prénom et Nom</label>
                <input 
                  type="text" 
                  className="form-input"
                  name="firstName"
                  value={`${userData.firstName} ${userData.lastName}`}
                  onChange={handleInputChange}
                />
              </div>
              
              <div className="form-group">
                <label>Email</label>
                <input 
                  type="email" 
                  className="form-input"
                  name="email"
                  value={userData.email}
                  onChange={handleInputChange}
                />
              </div>
              
              <div className="form-group">
                <label>Date de naissance</label>
                <input 
                  type="text" 
                  className="form-input"
                  name="birthDate"
                  value={userData.birthDate}
                  onChange={handleInputChange}
                />
              </div>
              
              <div className="form-group">
                <label>Mot de passe</label>
                <input 
                  type="password" 
                  className="form-input"
                  name="password"
                  value={userData.password}
                  onChange={handleInputChange}
                />
              </div>
              
              <div className="form-group">
                <label>Adresse</label>
                <input 
                  type="text" 
                  className="form-input"
                  name="address"
                  value={userData.address}
                  onChange={handleInputChange}
                />
              </div>
              
              <div className="form-group">
                <label>Code Postal</label>
                <input 
                  type="text" 
                  className="form-input"
                  name="postalCode"
                  value={userData.postalCode}
                  onChange={handleInputChange}
                />
              </div>
              
              <div className="form-group">
                <label>Ville</label>
                <input 
                  type="text" 
                  className="form-input"
                  name="city"
                  value={userData.city}
                  onChange={handleInputChange}
                />
              </div>
              
              <div className="form-group">
                <label>Pays</label>
                <input 
                  type="text" 
                  className="form-input"
                  name="country"
                  value={userData.country}
                  onChange={handleInputChange}
                />
              </div>
            </div>
            
            <button className="save-button" onClick={handleSave}>
              Enregistrer
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Profil;
